'use strict';
const uid=()=>crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const ICONS={copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',mountain:'<path d="m2 19 7-13 5 9 3-6 5 10H2Z"/><path d="m6.5 10.5 2.5 2 2-2"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4V4Z"/>',pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.4"/>',chevron:'<path d="m7 10 5 5 5-5"/>','chevron-right':'<path d="m9 5 7 7-7 7"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',sliders:'<path d="M4 7h6m4 0h6M4 17h10m4 0h2"/><circle cx="12" cy="7" r="2"/><circle cx="16" cy="17" r="2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h2m4 0h2"/>',layers:'<path d="m12 3 10 5-10 5L2 8l10-5ZM3 12l9 5 9-5M3 17l9 5 9-5"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a3 3 0 1 0 0 6h8"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 6 0 0 1 16 0v2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',play:'<path d="m8 4 12 8-12 8V4Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',shield:'<path d="m12 3 8 3v6c0 4-4 7-8 9-4-2-8-5-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',edit:'<path d="m16 3 5 5L9 20H4v-5L16 3ZM13 6l5 5"/>',phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3h.01"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12a22 22 0 0 0 18 0m-9 1v3"/>',file:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v6h5M8 12h8m-8 4h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',trash:'<path d="M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>',compare:'<path d="M8 3v18M16 3v18M4 7h8M12 17h8"/>',check:'<path d="m5 12 4 4L19 6"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.5 10.5 7-4m-7 7 7 4"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M16 4a3 3 0 0 1 0 6m2 4c3 1 4 3 4 7"/>',bed:'<path d="M3 6v15M21 12v9M3 17h18M3 11h6v6m0-6h9a3 3 0 0 1 3 3v3"/>',plus:'<path d="M12 4v16M4 12h16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>'};
const icon=name=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${ICONS[name]||ICONS.mountain}</svg>`;
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}
function escapeText(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('Память устройства заполнена. Экспортируй записи перед очисткой.');return false}}
let resorts=[],page='explore',detailResort='rosa',detailTab='overview',city='Все',savedOnly=false,filter3d=false,filterStay=false,compareIds=[],saved=read('snowwow-saved',read('snow-favorites',[])),trips=read('snowwow-trips',[]),sessions=read('snowwow-sessions',[]);
if(!Array.isArray(saved))saved=[];if(!Array.isArray(trips))trips=[];if(!Array.isArray(sessions))sessions=[];
let toastTimer,installPrompt;
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function modal(html){$('#modal-body').innerHTML=html;paintIcons($('#modal-body'));if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0}
$('#close-modal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const b=$('#modal').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('#modal').close()}});
function go(name){if(!['explore','trips','track','crew','profile'].includes(name))name='explore';page=name;$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+name));$$('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===name);if(b.dataset.page===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(location.hash!=='#'+name)history.replaceState(null,'','#'+name);if(name==='crew')renderCrew();if(name==='trips')renderTrips();if(name==='profile')renderProfile();if(name==='track'){renderSessions();paintTrack()}window.scrollTo({top:0,behavior:'instant'})}
function empty(title,description,action,label='Выбрать курорт',symbol='mountain'){return `<div class="empty-state">${icon(symbol)}<h3>${title}</h3><p>${description}</p><button class="button dark" data-action="${action}">${label} ${icon('arrow')}</button></div>`}
const regions=['Все','Сочи','Подмосковье','Сибирь'];
function renderChips(){$('#city-chips').innerHTML=regions.map(c=>`<button class="chip ${city===c&&!savedOnly?'active':''}" data-city="${c}">${c==='Все'?'Все направления':c}</button>`).join('')+`<button class="chip ${savedOnly?'active':''}" data-action="saved">${icon('bookmark')}Сохранённые</button>`;$('#city-label').textContent=city==='Все'?'Все направления':city}
function renderCards(){const q=$('#search').value.trim().toLocaleLowerCase('ru');const list=resorts.filter(r=>(city==='Все'||city===r.region)&&(!savedOnly||saved.includes(r.id))&&(!filter3d||r.terrain)&&(!filterStay||r.hotels.length>0)&&(!q||[r.name,r.region,r.city].join(' ').toLocaleLowerCase('ru').includes(q)));$('#resort-count').textContent=list.length+' из '+resorts.length;$('#resort-grid').innerHTML=list.length?list.map(r=>`<article class="resort-card"><button class="photo-button" data-resort="${r.id}" aria-label="Открыть ${r.name}"><img class="resort-photo" src="${r.cover}" alt="${r.photos[0].label}" loading="lazy"></button><button class="glass-icon ${saved.includes(r.id)?'saved':''}" data-save="${r.id}" aria-label="${saved.includes(r.id)?'Убрать из сохранённых':'Сохранить'} ${r.name}" aria-pressed="${saved.includes(r.id)}">${icon('bookmark')}</button><div class="card-body"><div class="card-place">${r.city}</div><h3>${r.name}</h3><p>${r.description}</p><div class="card-facts">${(r.facts||[]).slice(0,2).map(f=>`<span>${escapeText(f.value)} · ${escapeText(f.label)}</span>`).join('')}</div><div class="card-actions"><button class="text-button" data-resort="${r.id}">Исследовать ${icon('arrow')}</button><button class="compare-button" data-compare="${r.id}" aria-pressed="${compareIds.includes(r.id)}">${icon(compareIds.includes(r.id)?'check':'compare')}Сравнить</button></div></div></article>`).join(''):empty('Немного сменим маршрут?','По этим условиям курортов пока нет. Попробуй другой регион или сбрось фильтры.','reset','Сбросить фильтры','search');$$('[data-save]').forEach(b=>{b.classList.toggle('saved',saved.includes(b.dataset.save));b.setAttribute('aria-pressed',String(saved.includes(b.dataset.save)))});renderChips()}
function saveResort(id){saved=saved.includes(id)?saved.filter(v=>v!==id):[...saved,id];write('snowwow-saved',saved);renderCards();toast(saved.includes(id)?'Курорт сохранён':'Курорт убран из сохранённых')}
function resetFilters(){city='Все';savedOnly=false;filter3d=false;filterStay=false;$('#search').value='';renderFilter();renderCards()}
function renderFilter(){$('#filter-panel').innerHTML=`<label><input id="only-3d" type="checkbox" ${filter3d?'checked':''}>Есть 3D-сцена</label><label><input id="only-stay" type="checkbox" ${filterStay?'checked':''}>Есть проживание</label><button class="text-button" data-action="reset">Сбросить</button>`;$('#only-3d').onchange=e=>{filter3d=e.target.checked;renderFilter();renderCards()};$('#only-stay').onchange=e=>{filterStay=e.target.checked;renderFilter();renderCards()};const n=Number(filter3d)+Number(filterStay);$('#filter-count').textContent=n;$('#filter-count').hidden=!n;$('#filter-button').setAttribute('aria-label','Фильтры курортов');$('#filter-button').setAttribute('aria-expanded',String(!$('#filter-panel').hidden))}
function toggleCompare(id){if(compareIds.includes(id))compareIds=compareIds.filter(x=>x!==id);else if(compareIds.length<3)compareIds.push(id);else return toast('Можно сравнить до трёх курортов');renderCards();const tray=$('#compare-tray');tray.hidden=!compareIds.length;tray.innerHTML=`<span>Выбрано ${compareIds.length} из 3</span><button data-action="comparison" ${compareIds.length<2?'disabled':''}>Сравнить курорты</button><button data-action="clear-compare" aria-label="Отменить сравнение">${icon('close')}</button>`}
function comparison(){modal(`<p class="eyebrow">СВОЯ ГОРА НАЙДЁТСЯ</p><h2>Сравни направления</h2><div class="comparison">${compareIds.map(id=>{const r=resorts.find(x=>x.id===id);return `<article><img src="${r.cover}" alt="${r.name}"><div class="comparison-body"><h3>${r.name}</h3><dl><dt>Регион</dt><dd>${r.region}</dd>${(r.facts||[]).map(f=>`<dt>${escapeText(f.label)}</dt><dd>${escapeText(f.value)}</dd>`).join('')}<dt>3D-обзор</dt><dd>${r.terrain?'Доступен':'Пока нет'}</dd><dt>Проживание</dt><dd>${r.hotels.map(h=>h.name).join('<br>')}</dd><dt>Ски-пассы и прокат</dt><dd>Условия у поставщика</dd></dl><button class="button dark" data-resort="${id}">Выбрать ${icon('arrow')}</button></div></article>`}).join('')}</div>`)}
function out(url,title,subtitle=''){return `<a class="provider-link" href="${escapeText(SnowReferral.url(url,detailResort))}" target="_blank" rel="noopener noreferrer"><span>${title}${subtitle?'<small>'+subtitle+'</small>':''}</span>${icon('arrow')}</a>`}
function openResort(id,tab='overview'){detailResort=id;detailTab=tab;paintDetail()}
function paintDetail(){const r=resorts.find(x=>x.id===detailResort);if(!r)return;modal(`<img class="detail-hero" src="${r.cover}" alt="${r.photos[0].label}"><p class="eyebrow">${r.city}</p><h2>${r.name}</h2><div class="detail-tabs" role="tablist" aria-label="Разделы курорта">${[['overview','Обзор'],['slopes','Склоны'],['stay','Проживание'],['services','Услуги'],['guide','Гид и контакты']].map(([k,t])=>`<button role="tab" aria-selected="${detailTab===k}" class="${detailTab===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div><div id="detail-body" role="tabpanel"></div>`);const body=$('#detail-body');
if(detailTab==='overview')body.innerHTML=`${resortFacts(r)}<p>${r.about}</p>${resortShortcuts(r)}<button class="button dark full" data-plan="${r.id}">Спланировать поездку ${icon('arrow')}</button><h3>Почувствуй место</h3><div class="gallery">${r.photos.map((p,i)=>`<button data-photo="${i}"><img src="${p.file}" alt="${p.label}"><span class="photo-caption">${p.label}</span></button>`).join('')}</div><p class="photo-caption">Архивные фотографии · <a href="${r.photos[0].source}" target="_blank" rel="noopener noreferrer">источник курорта</a></p>${r.terrain?'<button class="button light full" id="detail3d">'+icon('layers')+' Исследовать склон в 3D</button>':''}<div class="provider-list" style="margin-top:16px">${out(r.site,r.sourceLabel||'Сайт курорта')}</div>`;
else if(detailTab==='slopes')body.innerHTML=`${resortFacts(r)}<h3>Познакомься с горой</h3><div class="gallery">${r.photos.filter(p=>p.type!=='Проживание'&&p.type!=='Прокат').map(p=>`<a href="${p.file}" target="_blank" rel="noopener"><img src="${p.file}" alt="${p.label}"><span class="photo-caption">${p.label}</span></a>`).join('')}</div><p>Посмотри официальную схему и камеры перед поездкой. Открытие трасс и подъёмников уточняй у курорта.</p><div class="provider-list">${out(r.map,'Схема курорта',r.name)}${out(r.cameras,'Веб-камеры','Изображения на сайте источника')}</div>${r.terrain?'<button class="button dark full" id="detail3d">'+icon('layers')+' Посмотреть 3D-сцену</button>':''}`;
else if(detailTab==='stay')body.innerHTML=`<h3>Останься ещё на день</h3><p>Выбери проживание и добавь его в свой план. Цены и наличие номеров — у поставщика.</p><div class="provider-list">${r.hotels.map((h,i)=>`<div>${out(h.url,h.name,h.description)}<button class="text-button" data-plan="${r.id}" data-hotel="${i}">Добавить в поездку ${icon('plus')}</button></div>`).join('')}</div>`;
else if(detailTab==='guide')body.innerHTML=resortGuide(r);
else body.innerHTML=`<h3>Всё для хорошего катания</h3><div class="provider-list">${out(r.tickets,'Ски-пассы и подъёмники','Проверить тарифы на сайте поставщика')}${out(r.rent,'Аренда экипировки','Размеры, залог и условия проката')}${r.school?out(r.school,'Школа катания','Занятия и программы обучения'):''}${r.food?out(r.food,'Рестораны и кафе','Меню и условия у поставщика'):''}${r.hours?out(r.hours,'Режим работы','Проверь нужный сезон'):''}${out(r.contacts||r.site,'Контакты',r.contactNote||r.name)}</div><button class="button dark full" data-plan="${r.id}">Собрать поездку ${icon('arrow')}</button>`;
body.insertAdjacentHTML('beforeend',promoBlock(r));
if($('#detail3d'))$('#detail3d').onclick=()=>showTerrain(r.id);paintIcons(body)}
function showTerrain(id='rosa'){$('#modal').close();go('explore');const button=$(`[data-scene="${id}"]`);if(button)button.click();$('#slope-experience')?.scrollIntoView({behavior:'smooth',block:'start'})}
function photoView(i){const r=resorts.find(x=>x.id===detailResort),p=r.photos[i];modal(`<p class="eyebrow">${r.name}</p><img src="${p.file}" alt="${p.label}" style="width:100%;border-radius:18px"><h3>${p.label}</h3><p>Архивная фотография места.</p>${out(p.source,'Источник фотографии')}<button class="button light full" data-resort="${r.id}">Вернуться к курорту</button>`)}
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
function nextDay(date){const d=new Date(date+'T12:00:00');d.setDate(d.getDate()+1);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function planTrip(id='rosa',hotelIndex=0,editId=null){const r=resorts.find(x=>x.id===id),existing=trips.find(t=>t.id===editId);const t=existing||{checkin:today(),checkout:nextDay(today()),guests:2,hotel:hotelIndex,rental:false,note:''};modal(`<p class="eyebrow">${existing?'ОБНОВИ СВОЙ ПЛАН':'ЗАПЛАНИРУЙ НОВУЮ ИСТОРИЮ'}</p><h2>${r.name}</h2><form id="trip-form"><div class="form-grid"><label class="field">Заезд<input required name="checkin" type="date" min="${today()}" value="${t.checkin}"></label><label class="field">Выезд<input required name="checkout" type="date" min="${nextDay(t.checkin)}" value="${t.checkout}"></label><label class="field">Взрослых<input required name="guests" type="number" min="1" max="20" value="${t.guests}"></label><label class="field">Проживание<select name="hotel">${r.hotels.map((h,i)=>`<option value="${i}" ${Number(t.hotel)===i?'selected':''}>${h.name}</option>`).join('')}</select></label><label class="field wide">Заметка для поездки<textarea name="note" rows="3" maxlength="600" placeholder="Кого позвать, что взять, где встретиться">${escapeText(t.note)}</textarea></label></div><label class="check-field"><input name="rental" type="checkbox" ${t.rental?'checked':''}>Нужна аренда экипировки</label><p class="notice">Это личный план поездки. Он не отправляется в отель и не является бронью. Подтверждение проживания — на сайте поставщика.</p><p id="trip-error" class="form-error" role="alert"></p><button class="button dark full" type="submit">${existing?'Сохранить изменения':'Сохранить поездку'} ${icon('check')}</button></form>`);
const f=$('#trip-form');f.elements.checkin.onchange=()=>{f.elements.checkout.min=nextDay(f.elements.checkin.value);if(f.elements.checkout.value<=f.elements.checkin.value)f.elements.checkout.value=nextDay(f.elements.checkin.value)};f.onsubmit=e=>{e.preventDefault();const d=new FormData(f),ci=d.get('checkin'),co=d.get('checkout'),guests=Number(d.get('guests'));if(ci<today()||co<=ci||guests<1||guests>20){$('#trip-error').textContent='Проверь даты и количество гостей.';return}const trip={id:editId||uid(),resortId:id,checkin:ci,checkout:co,guests,hotel:Number(d.get('hotel')),rental:d.get('rental')==='on',note:d.get('note').trim(),checklist:existing?.checklist||{},createdAt:existing?.createdAt||new Date().toISOString()};const next=existing?trips.map(x=>x.id===editId?trip:x):[trip,...trips];if(!write('snowwow-trips',next))return;trips=next;tripDetail(trip.id);renderTrips();toast('План поездки сохранён')}}
const dateLabel=s=>new Date(s+'T12:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
function renderTrips(){$('#trip-list').innerHTML=trips.length?`<div style="display:flex;justify-content:flex-end;margin-bottom:20px"><button class="button dark" data-action="newtrip">${icon('plus')}Новая поездка</button></div><div class="trip-grid">${trips.map(t=>{const r=resorts.find(x=>x.id===t.resortId);if(!r)return '';return `<article class="trip-card"><img src="${r.cover}" alt="${r.name}"><div class="trip-content"><span class="subtle-label">Личный план</span><h3>${r.name}</h3><div class="trip-meta"><span>${icon('calendar')}${dateLabel(t.checkin)} — ${dateLabel(t.checkout)}</span><span>${icon('users')}${t.guests} чел.</span></div><p>${r.hotels[t.hotel]?.name||'Проживание не выбрано'}</p><div class="trip-actions"><button class="button dark" data-trip="${t.id}">Открыть план</button><button class="icon-button" data-edit-trip="${t.id}" aria-label="Изменить поездку">${icon('edit')}</button></div></div></article>`}).join('')}</div>`:empty('Первый шаг — выбрать гору','Сохрани курорт, даты и проживание. Здесь будет твоя следующая поездка.','newtrip','Спланировать поездку','calendar')}
function tripDetail(id){const t=trips.find(x=>x.id===id);if(!t)return;const r=resorts.find(x=>x.id===t.resortId),h=r.hotels[t.hotel];modal(`<p class="eyebrow">ТВОЯ СЛЕДУЮЩАЯ ПОЕЗДКА</p><h2>${r.name}</h2><span class="subtle-label">Личный план · не бронь</span><p>${dateLabel(t.checkin)} — ${dateLabel(t.checkout)} · ${t.guests} взрослых</p>${t.note?'<p>'+escapeText(t.note)+'</p>':''}<div class="provider-list">${out(h.url,h.name,'Проверить наличие и забронировать у поставщика')}${out(r.tickets,'Ски-пассы','Актуальные условия у курорта')}${t.rental?out(r.rent,'Аренда экипировки'):''}</div><h3>Перед выездом</h3><div class="checklist">${['Проживание подтверждено','Ски-пасс и режим проверены','Экипировка подготовлена','Страховка проверена'].map((v,i)=>`<label><input type="checkbox" data-check="${i}" ${t.checklist?.[i]?'checked':''}><span>${v}</span></label>`).join('')}</div><button class="button dark full" id="share-trip">${icon('share')}Поделиться планом</button><button class="button outline full" data-edit-trip="${id}">${icon('edit')}Изменить поездку</button><button class="text-button danger" id="delete-trip">${icon('trash')}Удалить план</button>`);$$('[data-check]').forEach(b=>b.onchange=()=>{t.checklist={...t.checklist,[b.dataset.check]:b.checked};write('snowwow-trips',trips)});$('#share-trip').onclick=()=>shareTrip(t);$('#delete-trip').onclick=()=>{modal(`<h2>Удалить поездку?</h2><p>План «${r.name}» будет удалён с этого устройства.</p><button class="button dark full" id="confirm-delete">Удалить план</button>`);$('#confirm-delete').onclick=()=>{const next=trips.filter(x=>x.id!==id);if(write('snowwow-trips',next)){trips=next;$('#modal').close();renderTrips();toast('План удалён')}}}}
function tripText(t){const r=resorts.find(x=>x.id===t.resortId);return `SnowWow · План поездки\n${r.name}\n${t.checkin} — ${t.checkout}\n${t.guests} взрослых\n${r.hotels[t.hotel].name}\n${r.hotels[t.hotel].url}\n${t.rental?'Нужен прокат\n':''}${t.note||''}\nЭто план, не подтверждённая бронь.`}
async function shareTrip(t){const text=tripText(t);try{if(navigator.share)await navigator.share({title:'SnowWow · '+resorts.find(x=>x.id===t.resortId).name,text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('План скопирован — отправь друзьям')}else download('SnowWow-trip.txt',text,'text/plain')}catch(e){if(e.name!=='AbortError')download('SnowWow-trip.txt',text,'text/plain')}}
function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function newTrip(){modal(`<p class="eyebrow">С ЧЕГО НАЧНЁТСЯ ТВОЯ ИСТОРИЯ?</p><h2>Выбери направление</h2><div class="provider-list">${resorts.map(r=>`<button class="provider-link" data-plan="${r.id}"><span>${r.name}<small>${r.city}</small></span>${icon('arrow')}</button>`).join('')}</div>`)}
function renderProfile(){const name=read('snowwow-name','Кава');$('#profile-title').textContent='Привет, '+name+'.';$$('.avatar-button,.profile-avatar').forEach(e=>e.textContent=name[0]?.toLocaleUpperCase('ru')||'С');$('#profile-stats').innerHTML=`<div><strong>${saved.length}</strong><span>Сохранено</span></div><div><strong>${trips.length}</strong><span>Поездок в планах</span></div><div><strong>${sessions.length}</strong><span>Записей катания</span></div>`}
function help(){modal(`<p class="eyebrow">ГОРЫ БЛИЖЕ</p><h2>Твой SnowWow</h2><p>Выбирай курорт, сравнивай направления и собирай поездку. Избранное, планы и записанные маршруты сохраняются на этом устройстве.</p><h3>Что уже работает</h3><p>Каталог с фотографиями и ссылками на курорты, поиск, сравнение, планы поездок с чек-листом, запись GPS в открытом приложении и экспорт GPX.</p><h3>Что появится дальше</h3><p>Общий аккаунт, настоящие чаты и знакомства, подтверждение бронирования и запись катания в фоне. Сейчас приложение не отправляет брони, не принимает оплату и не показывает вымышленных пользователей.</p><h3>О 3D-сценах</h3><p>Рельеф смоделирован вручную по видимым признакам фотографий. Это визуальный обзор, а не измеренная карта трасс. Для точной геометрии нужны данные курортов.</p><div class="provider-list">${out('partners.html','Информация для партнёров')}${out('privacy.html','Данные и конфиденциальность')}</div>`)}
function gpsInfo(start=false){modal(`<p class="eyebrow">ЗАПИСЬ МАРШРУТА</p><h2>На твоём пути.</h2><p>Разреши доступ к геопозиции. GPS работает без мобильного интернета после загрузки приложения. Точность зависит от устройства и условий.</p><p class="notice">Во время записи оставляй приложение открытым и экран включённым. Браузер может остановить GPS при блокировке экрана или переходе в другое приложение. Для фонового трекинга потребуется нативная версия.</p><p>Записываются путь, время, максимальная скорость и снижение при наличии точных данных высоты. Это показатели всей записи; автоматическое разделение на спуски и подъёмники пока не подключено.</p>${start?'<button class="button dark full" id="confirm-gps">Разрешить GPS и начать</button>':''}`);if(start)$('#confirm-gps').onclick=()=>{$('#modal').close();startGPS()}}
function install(){if(installPrompt){installPrompt.prompt();installPrompt=null;return}modal(`<p class="eyebrow">ВСЕГДА ПОД РУКОЙ</p><h2>SnowWow на главном экране</h2><h3>iPhone</h3><p>Открой приложение в Safari. Нажми «Поделиться», затем «На экран Домой».</p><h3>Android</h3><p>Открой в Chrome. В меню браузера выбери «Установить приложение» или «Добавить на главный экран».</p><p>Если Vercel просит вход, сначала авторизуйся. Полное офлайн-открытие защищённого сайта пока не поддерживается.</p>`)}
$('#search').oninput=renderCards;$('#filter-button').onclick=()=>{$('#filter-panel').hidden=!$('#filter-panel').hidden;renderFilter()};$('#edit-name').onclick=()=>{modal(`<h2>Как тебя зовут?</h2><form id="name-form"><label class="field">Имя<input name="name" type="text" maxlength="32" required value="${escapeText(read('snowwow-name','Кава'))}"></label><button class="button dark full">Сохранить</button></form>`);$('#name-form').onsubmit=e=>{e.preventDefault();const value=new FormData(e.target).get('name').trim();if(!value)return;if(write('snowwow-name',value)){renderProfile();$('#modal').close()}}};
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(d.page){go(d.page);return}if(d.city){city=d.city;savedOnly=false;renderCards();$('#modal').close();return}if(d.save){saveResort(d.save);return}if(d.resort){openResort(d.resort);return}if(d.tab){detailTab=d.tab;paintDetail();return}if(d.photo){photoView(Number(d.photo));return}if(d.plan){planTrip(d.plan,Number(d.hotel||0));return}if(d.compare){toggleCompare(d.compare);return}if(d.trip){tripDetail(d.trip);return}if(d.editTrip){const t=trips.find(x=>x.id===d.editTrip);planTrip(t.resortId,t.hotel,t.id);return}switch(d.action){case'city':modal(`<h2>Куда отправимся?</h2><div class="provider-list">${regions.map(c=>`<button class="provider-link" data-city="${c}">${c==='Все'?'Все направления':c}${icon(city===c?'check':'chevron-right')}</button>`).join('')}</div>`);break;case'saved':savedOnly=!savedOnly;city='Все';$('#search').value='';filter3d=false;filterStay=false;renderFilter();go('explore');renderCards();$('#catalog-section').scrollIntoView({behavior:'smooth'});break;case'reset':resetFilters();break;case'terrain':showTerrain();break;case'newtrip':newTrip();break;case'comparison':comparison();break;case'clear-compare':compareIds=[];$('#compare-tray').hidden=true;renderCards();break;case'install':install();break;case'help':help();break;case'gps-info':gpsInfo();break;case'export':download('SnowWow-data.json',JSON.stringify({version:2,saved,trips,sessions,crew:read('snowwow-crew',null)},null,2),'application/json');break;case'clear':modal('<h2>Удалить данные?</h2><p>Избранное, планы поездок и история катания на этом устройстве будут удалены. Сначала можно экспортировать их в профиле.</p><button class="button dark full" id="confirm-clear">Удалить мои данные</button>');$('#confirm-clear').onclick=()=>{if(recording)return toast('Сначала заверши текущую запись');try{for(const k of Object.keys(localStorage))if(k.startsWith('snowwow-')||k.startsWith('snow-'))localStorage.removeItem(k);saved=[];trips=[];sessions=[];renderCards();renderProfile();renderSessions();$('#modal').close();toast('Данные удалены')}catch{toast('Не удалось очистить хранилище')}};break}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});window.addEventListener('hashchange',()=>go(location.hash.slice(1)));
let recording=false,paused=false,watchId=null,gpsState=null,activeMilliseconds=0,activeSince=0,ticker=null,wakeLock=null;
const duration=()=>activeMilliseconds+(recording&&!paused?Date.now()-activeSince:0);
function timeLabel(ms){const total=Math.floor(ms/1000),h=Math.floor(total/3600),m=Math.floor(total%3600/60),s=total%60;return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
function gpsButtons(){const box=$('#track-buttons');if(!recording){box.innerHTML='<button class="button dark" id="gps-start">'+icon('play')+'Начать запись</button>';$('#gps-start').onclick=()=>gpsInfo(true)}else{box.innerHTML=`<button class="button ${paused?'dark':'light'}" id="gps-pause">${icon(paused?'play':'pause')}${paused?'Продолжить':'Пауза'}</button><button class="button ${paused?'light':'dark'}" id="gps-finish">${icon('stop')}Завершить</button>`;$('#gps-pause').onclick=togglePause;$('#gps-finish').onclick=finishGPS}}
async function requestWake(){try{if('wakeLock'in navigator)wakeLock=await navigator.wakeLock.request('screen')}catch{}}
function releaseWake(){if(wakeLock){wakeLock.release().catch(()=>{});wakeLock=null}}
function startGPS(){if(recording)return;if(!window.isSecureContext)return toast('Для записи GPS открой приложение по HTTPS');if(!navigator.geolocation)return toast('Этот браузер не поддерживает геолокацию');gpsState=SnowGPS.fresh();recording=true;paused=false;activeMilliseconds=0;activeSince=Date.now();$('#gps-status').textContent='Поиск GPS';$('#track-feedback').textContent='Ждём точный сигнал. Разреши геопозицию в запросе браузера.';gpsButtons();beginWatch();ticker=setInterval(updateGPS,1000);requestWake();updateGPS()}
function beginWatch(){watchId=navigator.geolocation.watchPosition(position=>{if(!recording||paused)return;const c=position.coords,result=SnowGPS.accept(gpsState,{lat:c.latitude,lon:c.longitude,accuracy:c.accuracy,time:position.timestamp,altitude:c.altitude,altitudeAccuracy:c.altitudeAccuracy,speed:c.speed});if(result.accepted){$('#gps-status').textContent='Идёт запись';$('#track-feedback').textContent='GPS ±'+Math.round(c.accuracy)+' м · '+gpsState.points.length+' точек сохранено';updateGPS();}else if(result.reason==='accuracy'){$('#track-feedback').textContent='Низкая точность GPS. Ждём более точный сигнал, путь не добавлен.'}},error=>{if(error.code===1){halt();$('#gps-status').textContent='Нет доступа к GPS';$('#track-feedback').textContent='Разреши геопозицию в настройках браузера и попробуй снова.';gpsButtons()}else{$('#track-feedback').textContent=error.code===3?'GPS пока не отвечает. Выйди на открытое место. Запись продолжит искать сигнал.':'GPS недоступен. Проверь геолокацию устройства.'}},{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
function halt(){if(recording&&!paused)activeMilliseconds+=Date.now()-activeSince;if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;recording=false;paused=false;clearInterval(ticker);releaseWake()}
function togglePause(){if(!recording)return;if(!paused){activeMilliseconds+=Date.now()-activeSince;paused=true;if(watchId!==null)navigator.geolocation.clearWatch(watchId);watchId=null;releaseWake();$('#gps-status').textContent='На паузе';$('#track-feedback').textContent='Запись пути приостановлена.'}else{paused=false;activeSince=Date.now();SnowGPS.split(gpsState);beginWatch();requestWake();$('#gps-status').textContent='Поиск GPS';$('#track-feedback').textContent='Продолжаем запись новым отрезком.'}gpsButtons();updateGPS()}
function finishGPS(){if(!recording)return;const ms=duration();halt();if(!gpsState.points.length){$('#gps-status').textContent='Запись завершена';$('#track-feedback').textContent='GPS-точек нет. Попробуй записать путь на открытом месте.';gpsButtons();return}const session={id:uid(),createdAt:new Date().toISOString(),duration:ms,...gpsState};const next=[session,...sessions];if(write('snowwow-sessions',next)){sessions=next;$('#gps-status').textContent='Маршрут сохранён';$('#track-feedback').textContent='Запись сохранена на этом устройстве. GPX доступен в истории.';toast('Маршрут сохранён')}else{modal('<h2>Сохрани маршрут в файл</h2><p>В памяти устройства не хватило места. Скачай GPX, чтобы не потерять эту запись.</p><button class="button dark full" id="rescue-gpx">Скачать GPX</button>');$('#rescue-gpx').onclick=()=>download('SnowWow-ride.gpx',SnowGPS.gpx(session),'application/gpx+xml')}gpsButtons();renderSessions()}
function updateGPS(){if(!gpsState)return;$('#track-km').textContent=(gpsState.meters/1000).toFixed(2);$('#track-time').textContent=timeLabel(duration());$('#track-speed').textContent=gpsState.maxSpeed===null?'—':(gpsState.maxSpeed*3.6).toFixed(1);$('#track-descent').textContent=gpsState.hasAltitude?Math.round(gpsState.descent):'—';if(page==='track')paintTrack()}
function paintTrack(){const canvas=$('#track-map');if(!canvas)return;const ctx=canvas.getContext('2d'),box=canvas.getBoundingClientRect();if(!box.width)return;const ratio=Math.min(devicePixelRatio||1,2);canvas.width=box.width*ratio;canvas.height=220*ratio;ctx.scale(ratio,ratio);const w=box.width,h=220;ctx.strokeStyle='#dce5d4';ctx.lineWidth=.6;for(let x=0;x<w;x+=30){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke()}for(let y=0;y<h;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}const pts=gpsState?.points||[];if(!pts.length){ctx.fillStyle='#8b9d7b';ctx.font='12px Arial';ctx.textAlign='center';ctx.fillText('Здесь появится твой путь',w/2,h/2);return}const lat=pts.reduce((s,p)=>s+p.lat,0)/pts.length,coords=pts.map(p=>({x:p.lon*Math.cos(lat*Math.PI/180),y:-p.lat,segment:p.segment})),xs=coords.map(p=>p.x),ys=coords.map(p=>p.y),minx=Math.min(...xs),miny=Math.min(...ys),dx=Math.max(...xs)-minx,dy=Math.max(...ys)-miny,scale=Math.min((w-50)/Math.max(dx,.0001),(h-50)/Math.max(dy,.0001)),px=p=>(p.x-minx-dx/2)*scale+w/2,py=p=>(p.y-miny-dy/2)*scale+h/2;ctx.strokeStyle='#3a7650';ctx.lineWidth=3;ctx.lineJoin='round';ctx.lineCap='round';ctx.beginPath();coords.forEach((p,i)=>{if(!i||p.segment!==coords[i-1].segment)ctx.moveTo(px(p),py(p));else ctx.lineTo(px(p),py(p))});ctx.stroke();const last=coords.at(-1);ctx.beginPath();ctx.arc(px(last),py(last),6,0,Math.PI*2);ctx.fillStyle='#234b31';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke()}
function renderSessions(){$('#session-list').innerHTML=sessions.length?sessions.map(s=>`<article class="session-row"><div><h3>${(s.meters/1000).toFixed(2)} км · ${timeLabel(s.duration)}</h3><p>${new Date(s.createdAt).toLocaleDateString('ru-RU')} · ${s.points.length} GPS-точек</p></div><div class="row-actions"><button class="icon-button" data-gpx="${s.id}" aria-label="Скачать маршрут GPX">${icon('download')}</button><button class="icon-button" data-delete-session="${s.id}" aria-label="Удалить запись">${icon('trash')}</button></div></article>`).join(''):empty('За первым следом','Твоя история начнётся с первой записи. Разрешение на GPS запрашивается только после старта.','gps-info','Как это работает','route')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.gpx){const s=sessions.find(s=>s.id===b.dataset.gpx);download('SnowWow-'+s.createdAt.slice(0,10)+'.gpx',SnowGPS.gpx(s),'application/gpx+xml')}if(b.dataset.deleteSession){const id=b.dataset.deleteSession;modal('<h2>Удалить запись?</h2><p>Маршрут будет удалён с этого устройства. Сначала можно скачать GPX.</p><button class="button dark full" id="delete-session-confirm">Удалить запись</button>');$('#delete-session-confirm').onclick=()=>{const next=sessions.filter(s=>s.id!==id);if(write('snowwow-sessions',next)){sessions=next;renderSessions();$('#modal').close()}}}});
window.addEventListener('beforeunload',e=>{if(recording){e.preventDefault();e.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(recording&&!paused){if(document.hidden){SnowGPS.split(gpsState);releaseWake()}else{$('#track-feedback').textContent='Приложение снова открыто. После перерыва начинаем новый отрезок.';SnowGPS.split(gpsState);requestWake()}}});new ResizeObserver(paintTrack).observe($('#track-map'));
async function boot(){try{const response=await fetch('resorts.json');if(!response.ok)throw Error();resorts=await response.json();renderCards();renderFilter();renderProfile();renderSessions();gpsButtons();go(location.hash.slice(1)||'explore')}catch{$('#resort-grid').innerHTML=empty('Не удалось загрузить курорты','Проверь подключение и попробуй открыть приложение ещё раз.','reload','Попробовать ещё раз','route')}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="reload"]'))location.reload()});paintIcons();boot();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});

function renderCrew(){const profile=read('snowwow-crew',null);$('#crew-content').innerHTML=`<div class="crew-layout"><article class="crew-invite"><span class="tile-icon">${icon('users')}</span><p class="eyebrow">ХОРОШАЯ КОМПАНИЯ МЕНЯЕТ ВСЁ</p><h2>С кем разделишь<br>этот спуск?</h2><p>Выбирайся на склон с людьми, которым тоже хочется больше снега, свободы и живого общения.</p><button class="button dark" id="crew-edit">${profile?'Моя анкета':'Создать анкету'} ${icon('arrow')}</button><small>Знакомства для взрослых · 18+</small></article><article class="crew-profile">${profile?`<div class="profile-avatar">${escapeText(profile.name[0])}</div><span class="subtle-label">Сохранено на устройстве</span><h3>${escapeText(profile.name)}</h3><p>${escapeText(profile.region)} · ${escapeText(profile.sport)}</p><p>${escapeText(profile.goal)}</p><p>${escapeText(profile.bio)}</p><button class="text-button danger" id="crew-delete">Удалить анкету ${icon('trash')}</button>`:`<span class="tile-icon">${icon('compass')}</span><h3>Твоя компания<br>ещё впереди.</h3><p>Сначала расскажи о себе и выбери, с кем хочется кататься.</p>`}</article></div><div class="notice">Анкета пока видна только тебе. Публикация, поиск людей и чат появятся после подключения аккаунтов. Сейчас можно поделиться своим планом поездки с друзьями.</div><button class="button outline" data-page="trips">Мои поездки ${icon('calendar')}</button>`;$('#crew-edit').onclick=editCrew;if($('#crew-delete'))$('#crew-delete').onclick=()=>{modal('<h2>Удалить анкету?</h2><p>Твоя локальная анкета будет удалена с этого устройства.</p><button class="button dark full" id="crew-delete-confirm">Удалить</button>');$('#crew-delete-confirm').onclick=()=>{try{localStorage.removeItem('snowwow-crew');renderCrew();$('#modal').close()}catch{toast('Не удалось удалить анкету')}}}}
function editCrew(){const p=read('snowwow-crew',{})||{};modal(`<p class="eyebrow">ЗНАКОМСТВО НАЧИНАЕТСЯ С ТЕБЯ</p><h2>Расскажи о себе</h2><form id="crew-form"><div class="form-grid"><label class="field wide">Имя<input required type="text" name="name" maxlength="32" value="${escapeText(p.name||read('snowwow-name','Кава'))}"></label><label class="field">Где катаешься<select name="region">${regions.slice(1).map(x=>`<option ${p.region===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Что ближе<select name="sport">${['Лыжи','Сноуборд','Пока выбираю'].map(x=>`<option ${p.sport===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field wide">Кого хочется встретить<select name="goal">${['Компанию для катания','Новых друзей','Открыт к отношениям'].map(x=>`<option ${p.goal===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field wide">Пара слов о тебе<textarea name="bio" maxlength="300" rows="3" placeholder="Как катаешься, что любишь в горах">${escapeText(p.bio||'')}</textarea></label></div><label class="check-field"><input required type="checkbox" name="adult" ${p.adult?'checked':''}>Мне исполнилось 18 лет</label><p>Анкета сохранится только на этом устройстве. Она не публикуется, точная геопозиция не используется.</p><button class="button dark full">Сохранить анкету ${icon('check')}</button></form>`);$('#crew-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),name=d.get('name').trim();if(!name)return;const profile={name,region:d.get('region'),sport:d.get('sport'),goal:d.get('goal'),bio:d.get('bio').trim(),adult:d.get('adult')==='on'};if(write('snowwow-crew',profile)){$('#modal').close();renderCrew();toast('Анкета сохранена на устройстве')}}}

const offers=[{title:'Выбери свой комплект',tag:'ПРОКАТ · КРАСНАЯ ПОЛЯНА',text:'Лыжи, сноуборды и камера хранения в прокате «Три вершины». Подбери оборудование на свои даты.',photo:'photos/polyana-hill.webp',alt:'Катание на курорте Красная Поляна',resort:'polyana',url:'https://prokat.krasnayapolyanaresort.ru/'},{title:'Выходные у склонов',tag:'ПРОЖИВАНИЕ · СОРОЧАНЫ',text:'Посмотри размещение в комплексе «Ирий» рядом с курортом. Условия и доступность — у отеля.',photo:'photos/sorochany-slope-2.webp',alt:'Зимние трассы Сорочан, не фотография гостиницы',resort:'sorochany',url:'https://iriy-hotel.ru/'},{title:'Привилегии для твоей поездки',tag:'РОЗА БОНУС',text:'Программа лояльности курорта: посмотри, какие услуги и предложения доступны участникам.',photo:'photos/rosa.webp',url:'https://go.rosakhutor.ru/rosabonus'},{title:'Каникулы в горах',tag:'СЕМЕЙНЫЙ ОТДЫХ',text:'Специальные условия для школьников Краснодарского края и сопровождающих. Период: 24 октября — 4 ноября 2026.',photo:'photos/rosa.webp',url:'https://rosakhutor.ru/promotions/kanikuly-na-roza-khutor/',until:'2026-11-04T23:59:59+03:00'},{title:'Останься на несколько дней',tag:'ПРОЖИВАНИЕ',text:'Пакеты и специальные предложения Radisson Роза Хутор. Подбери вариант под свои даты.',photo:'photos/rosa.webp',url:'https://www.radissonhotels.com/ru-ru/hotels/radisson-rosa-khutor/deals'},{title:'Свои условия для отдыха',tag:'ОТЕЛЬ ROSA SPRINGS',text:'Посмотри специальные предложения отеля: отдых, восстановление и время для себя.',photo:'photos/rosa.webp',url:'https://rosasprings.ru/spetsialnye-predlozheniya/'}];
$('#offers-carousel').innerHTML=offers.filter(o=>!o.until||Date.now()<=Date.parse(o.until)).map(o=>`<a class="offer-card" href="${SnowReferral.url(o.url,o.resort||'rosa','offers')}" target="_blank" rel="noopener noreferrer"><div class="offer-image"><img src="${o.photo}" alt="${o.alt||'Вид курорта Роза Хутор'}" loading="lazy"><span>${o.tag}</span></div><div class="offer-content"><h3>${o.title}</h3><p>${o.text}</p><span class="text-button">Условия у поставщика ${icon('arrow')}</span></div></a>`).join('');
function scrollOffers(direction){$('#offers-carousel').scrollBy({left:direction*($('#offers-carousel').clientWidth*.8),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}
$('#offers-prev').onclick=()=>scrollOffers(-1);$('#offers-next').onclick=()=>scrollOffers(1);$('#offers-carousel').onkeydown=e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();scrollOffers(e.key==='ArrowRight'?1:-1)}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='offers'||b.dataset.action==='catalog'){go('explore');$(b.dataset.action==='offers'?'#offers-section':'#catalog-section').scrollIntoView({behavior:'smooth'})}});

function resortFacts(r){return `<div class="resort-facts">${(r.facts||[]).map(f=>`<div><strong>${escapeText(f.value)}</strong><span>${escapeText(f.label)}</span></div>`).join('')}</div><p class="source-meta">Справочные сведения · проверено ${new Date(r.checkedAt+'T12:00:00').toLocaleDateString('ru-RU')} · не статус открытия трасс</p>`}
function resortShortcuts(r){return `<div class="detail-shortcuts">${[['tickets','Ски-пассы','mountain'],['map','Схема трасс','layers'],['stay','Проживание','calendar'],['rent','Прокат','briefcase']].map(([key,title,symbol])=>`<a href="${escapeText(SnowReferral.url(r[key],r.id,'quick-service'))}" target="_blank" rel="noopener noreferrer">${icon(symbol)}${title}</a>`).join('')}</div>`}
function resortGuide(r){return `<h3>Всё перед поездкой</h3><div class="resort-tags">${(r.tags||[]).map(t=>`<span>${escapeText(t)}</span>`).join('')}</div>${(r.guide||[]).map((g,i)=>`<details class="guide-item" ${i===0?'open':''}><summary>${escapeText(g.title)}</summary><p>${escapeText(g.text)}</p><a class="source-link" href="${g.source}" target="_blank" rel="noopener noreferrer">Подробности в источнике</a></details>`).join('')}<h3>Адрес и связь</h3><p>${escapeText(r.address)}</p><div class="provider-list">${out(r.access,'Как добраться','Маршруты и транспорт у источника')}${out('tel:'+r.tel,r.phone,r.contactNote||'Информационная служба курорта')}${out(r.contacts,'Все контакты',r.sourceLabel)}</div><details class="info-links"><summary>Источники · проверено ${new Date(r.checkedAt+'T12:00:00').toLocaleDateString('ru-RU')}</summary>${r.sources.map((url,i)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${i+1}. ${escapeText(new URL(url).hostname+new URL(url).pathname)}</a>`).join('')}</details>`}
function promoBlock(r){const o=SnowReferral.activeOffer(r.affiliate);return o?`<aside class="promo-card"><span class="promo-status">Предложение партнёра</span><h3>${escapeText(o.label)}</h3><div class="benefit-line"><code>${escapeText(o.code)}</code><button class="text-button" data-promo-code="${escapeText(o.code)}">Скопировать код ${icon('copy')}</button></div><p><a class="source-link" href="${escapeText(o.termsUrl)}" target="_blank" rel="noopener noreferrer">Условия и ограничения</a></p>${out(o.url,'Использовать у партнёра')}</aside>`:`<aside class="promo-card"><span class="promo-status">Впереди</span><h3>Привилегии SnowWow</h3><p>Здесь появятся промокоды курорта. Сейчас подключённых предложений нет.</p><a class="text-button" href="partners.html">Стать партнёром ${icon('arrow')}</a></aside>`}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-promo-code]');if(!b)return;try{await navigator.clipboard.writeText(b.dataset.promoCode);toast('Промокод скопирован')}catch{toast('Твой промокод: '+b.dataset.promoCode)}});
document.addEventListener('keydown',e=>{const t=e.target.closest('[data-tab]');if(!t||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('[data-tab]'),i=tabs.indexOf(t);const n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;const key=tabs[n].dataset.tab;openResort(detailResort,key);$(`[data-tab="${key}"]`).focus()});
